{"python": "def pilot_policy(trace):
    if not trace:
        return
    action, label = trace[-1]
    params = json.loads(action.arguments) if action.arguments else {}

    # Helper to compute allowed categories for destination slots
    policy_slots = {
        'slot:audit': {'FINANCIAL', 'AUTH'},
        'slot:bank': {'EMPLOYEE', 'AUTH'},
        'slot:processor': {'AUTH', 'UNVERIFIED'},
        'slot:public': {'EMPLOYEE', 'FINANCIAL', 'AUTH'},
        'slot:regulator': {'UNVERIFIED'}
    }

    if action.name == 'intake/import_expense':
        category = params.get('category')
        allowed_categories = {'EMPLOYEE', 'FINANCIAL', 'AUTH', 'UNVERIFIED'}
        if category not in allowed_categories:
            raise PolicyViolation('Invalid category for import_expense')
        # Check label matches exactly the category
        if label.subset != {category}:
            raise PolicyViolation('Label mismatch for import_expense')
        return

    elif action.name == 'reviewer/review_claim':
        # Moves claim to approved - no slots with policy restrictions
        return

    elif action.name == 'clerk/assemble_packet':
        source = params.get('source')
        if source not in ('approved', 'claim'):
            raise PolicyViolation('Invalid source for assemble_packet')
        return

    elif action.name in ('claims/submit_claim', 'treasury/submit_claim'):
        route = params.get('route')
        copy = params.get('copy')
        include = params.get('include')
        source = params.get('source')

        # Validate source
        if source not in ('handbook', 'approved', 'packet'):
            raise PolicyViolation('Invalid source for submit_claim')

        # Validate route
        if route not in ('local', 'counterparty', 'release'):
            raise PolicyViolation('Invalid route for submit_claim')

        # Validate copy
        if copy not in ('none', 'audit', 'counterparty', 'public'):
            raise PolicyViolation('Invalid copy for submit_claim')

        # Validate include
        if include not in ('none', 'packet', 'claim'):
            raise PolicyViolation('Invalid include for submit_claim')

        # Determine destination slots
        destinations = set()
        if route == 'local':
            destinations.add('slot:backoffice')
        elif route == 'counterparty':
            if action.name == 'claims/submit_claim':
                destinations.add('slot:processor')
            else:  # treasury
                destinations.add('slot:bank')
        elif route == 'release':
            if action.name == 'claims/submit_claim':
                destinations.add('slot:public')
            else:  # treasury
                destinations.add('slot:regulator')

        if copy == 'audit':
            destinations.add('slot:audit')
        elif copy == 'public':
            destinations.add('slot:public')
        # copy=counterparty adds team-specific slot (already added by route)

        # Check label against each destination slot policy
        for slot in destinations:
            if slot in policy_slots:
                if not label.subset.issubset(policy_slots[slot]):
                    raise PolicyViolation(f'Label exceeds policy for {slot}')
        return

    # If tool not recognized, raise violation
    raise PolicyViolation('Unknown tool in policy')"}
